def quoted_span(text):
    return text.startswith('\"') and text.endswith('\"')

def strip_comments(text):
    return text.split('#', 1)[0]

def escaped_delimiter(text):
    return text.replace('\\,', ',')

def token_count(text):
    return len(text.split())

